  await test('archive, blocked permanent delete, restore, and hidden listing state preserve history',async()=>{await request(`/api/admin/territories/${vic.id}/product/${product.id}`,{method:'DELETE'});let item=(await request(`/api/admin/company-stock/catalog?territory_id=${vic.id}`)).data.catalog.find(x=>x.id===product.id);assert.equal(!!item.archived,true);const blocked=await request(`/api/admin/products/${product.id}/permanent`,{method:'DELETE',ok:false});assert.equal(blocked.status,400);assert.match(blocked.data.error,/history|orders|movements/i);await request(`/api/admin/products/${product.id}/restore`,{method:'POST',body:{}});item=(await request(`/api/admin/company-stock/catalog?territory_id=${vic.id}`)).data.catalog.find(x=>x.id===product.id);assert.equal(!!item.archived,false);assert.equal(!!item.selected_territory.listed,false);await request(`/api/admin/territories/${vic.id}/product/${product.id}`,{method:'PUT',body:{listed:true,featured:false,sort_order:0}});});
